// Leak: event handler keeps OrderService alive
public class OrderProcessor
{
    public OrderProcessor(IEventBus bus)
    {
        bus.OrderCreated += OnOrderCreated; // Never unsubscribed
    }

    private void OnOrderCreated(object sender, OrderEventArgs e)
    {
        // Process order...
    }
}

// Fix: unsubscribe or use weak events
public class OrderProcessor : IAsyncDisposable
{
    private readonly IEventBus _bus;

    public OrderProcessor(IEventBus bus)
    {
        _bus = bus;
        _bus.OrderCreated += OnOrderCreated;
    }

    public async ValueTask DisposeAsync()
    {
        _bus.OrderCreated -= OnOrderCreated;
        await Task.CompletedTask;
    }
}
